      "anyOf": [
        {
          "minimum": 0,
          "type": "integer"
        },
        {
          "type": "null"
        }
      ],
      "title": "Prep Time Minutes"
    },
    "difficulty": {
      "anyOf": [
        {
          "enum": [
            "easy",
            "medium",
            "hard"
          ],
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "title": "Difficulty"
    },
    "main_allergen": {
      "anyOf": [
        {
          "enum": [
            "celery",
            "cereals_containing_gluten",
            "crustaceans",
            "eggs",
            "fish",
            "lupin",
            "milk",
            "molluscs",
            "mustard",
            "nuts",
            "peanuts",
            "sesame",
            "soya",
            "sulphur_dioxide_and_sulphites"
          ],
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "title": "Main Allergen"
    },
    "substitution": {
      "anyOf": [
        {
          "$ref": "#/$defs/Substitution"
        },
        {
          "type": "null"
        }
      ]
    },
    "notes": {
      "items": {
        "type": "string"
      },
      "title": "Notes",
      "type": "array"
    }
  },
  "required": [
    "title",
    "ingredients",
    "allergens",
    "possible_allergens",
    "diet",
    "prep_time_minutes",
    "difficulty",
    "main_allergen",
    "substitution",
    "notes"
